def open_existing(path, *, timeout=5, readonly=False, code='DATABASE_UNAVAILABLE', message='业务数据库不可用，请检查配置或恢复已有数据库。'):
    path = Path(path).expanduser().resolve()
    try:
        if not path.is_file():
            raise OSError('Expected an existing database file')
