            CREATE TABLE IF NOT EXISTS agent_steps (
              task_id TEXT NOT NULL, agent_id TEXT NOT NULL, state TEXT NOT NULL,
              summary TEXT NOT NULL, started_at TEXT, finished_at TEXT, error_code TEXT,
              PRIMARY KEY(task_id,agent_id));
            CREATE TABLE IF NOT EXISTS agent_artifacts (
              task_id TEXT NOT NULL, agent_id TEXT NOT NULL, version INTEGER NOT NULL,
              content_json TEXT NOT NULL, content_hash TEXT NOT NULL, created_at TEXT NOT NULL,
              PRIMARY KEY(task_id,agent_id,version));
            CREATE TABLE IF NOT EXISTS agent_events (
              task_id TEXT NOT NULL, sequence INTEGER NOT NULL, payload_json TEXT NOT NULL,
              PRIMARY KEY(task_id,sequence));
            """
TASK_DATABASE_MESSAGE = 'Agent任务数据库缺失、路径错误或不可读取，请检查配置并恢复原库；未自动创建或修复。'


class TaskStore:
    def __init__(self, path: Path, *, create=False):
        self.path = Path(path).expanduser().resolve()
        options = {'code': 'AGENT_DATABASE_UNAVAILABLE', 'message': TASK_DATABASE_MESSAGE}
        if create:
            initialize_database(self.path, TASK_SCHEMA, TASK_TABLES, **options)
        else:
            validate_database(self.path, TASK_TABLES, **options)

    @contextmanager
    def connect(self):
        db = open_existing(self.path, timeout=5, code='AGENT_DATABASE_UNAVAILABLE', message=TASK_DATABASE_MESSAGE)
        try:
            db.row_factory = sqlite3.Row
            with db:
                yield db
        except sqlite3.Error:
            raise ServiceError('AGENT_DATABASE_UNAVAILABLE', TASK_DATABASE_MESSAGE, 503) from None
        finally:
            db.close()

    @staticmethod
    def signature(brief):
        return hashlib.sha256(json.dumps(brief, ensure_ascii=False, sort_keys=True).encode('utf-8')).hexdigest()

    def _row(self, db, task_id):
        row = db.execute('SELECT * FROM agent_tasks WHERE task_id=?', (task_id,)).fetchone()
        if row is None:
            raise ServiceError('AGENT_TASK_NOT_FOUND', '未找到这个创作任务，请检查任务标识。', 404)
        return row

    def _event(self, db, task_id, kind, state, summary, agent_id=None, **extras):
        row = self._row(db, task_id)
        sequence = row['sequence'] + 1
        stamp = now()
        payload = {'kind': kind, 'runId': task_id, 'sequence': sequence, 'occurredAt': stamp,
                   'summary': summary}
        if kind == 'agent':
            payload.update(agentId=agent_id, state=state)
        else:
            payload.update(taskState=state)
        payload.update({key: value for key, value in extras.items() if value is not None})
        db.execute('INSERT INTO agent_events VALUES (?,?,?)', (task_id, sequence, encode(payload)))
        db.execute('UPDATE agent_tasks SET sequence=?,updated_at=? WHERE task_id=?', (sequence, stamp, task_id))

    def existing(self, key, brief):
        with self.connect() as db:
            row = db.execute('SELECT task_id,signature FROM agent_tasks WHERE idempotency_key=?', (key,)).fetchone()
        if row is None:
            return None
        if row['signature'] != self.signature(brief):
            raise ServiceError('IDEMPOTENCY_CONFLICT', '同一提交标识不能用于不同创作需求。', 409)
        return row['task_id']

    def create(self, brief, key, queue_limit=2):
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            existing = db.execute('SELECT task_id,signature FROM agent_tasks WHERE idempotency_key=?', (key,)).fetchone()
            if existing:
                if existing['signature'] != self.signature(brief):
                    raise ServiceError('IDEMPOTENCY_CONFLICT', '同一提交标识不能用于不同创作需求。', 409)
                return existing['task_id'], False
            if brief.get('parentTaskId'):
                self._row(db, brief['parentTaskId'])
            count = db.execute("SELECT count(*) FROM agent_tasks WHERE state IN ('waiting','running')").fetchone()[0]
            if count >= queue_limit + 1:
                raise ServiceError('AGENT_QUEUE_FULL', '创作任务队列已满，请等待当前任务或稍后手动提交。', 429, True)
            task_id, stamp = str(uuid.uuid4()), now()
            db.execute('INSERT INTO agent_tasks VALUES (?,?,?,?,?,?,NULL,NULL,NULL,0,?,?)',
                       (task_id, key, self.signature(brief), encode(brief), 'waiting', 0, stamp, stamp))
            for agent_id in AGENTS:
                db.execute('INSERT INTO agent_steps VALUES (?,?,?, ?,NULL,NULL,NULL)',
                           (task_id, agent_id, 'pending', '尚未执行。'))
            self._event(db, task_id, 'task', 'waiting', '任务已保存，等待真实工作流调度。')
            return task_id, True

    def brief(self, task_id):
        with self.connect() as db:
            return json.loads(self._row(db, task_id)['brief_json'])

    def next_waiting(self):
        with self.connect() as db:
            row = db.execute("SELECT task_id FROM agent_tasks WHERE state='waiting' ORDER BY created_at LIMIT 1").fetchone()
            return row['task_id'] if row else None

    def start(self, task_id):
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            row = self._row(db, task_id)
            if row['state'] != 'waiting':
                return False
"""SQLite is the canonical source of evidence, never generated model citations."""
import json
import re
import sqlite3
from pathlib import Path
from ..database import open_existing, validate_database, initialize_database

def lexical_tokens(text: str) -> str:
    tokens = re.findall(r'[a-z0-9]+', text.lower())
    for run in re.findall(r'[\u4e00-\u9fff]+', text):
        tokens.extend(run)
        tokens.extend(run[i:i+2] for i in range(len(run)-1))
    return ' '.join(dict.fromkeys(tokens))

KNOWLEDGE_TABLES = {
    'sources': ('source_id', 'data_json'),
    'documents': ('document_id', 'source_id', 'version', 'content_hash'),
    'chunks': ('chunk_id', 'source_id', 'section_id', 'content_hash', 'data_json'),
    'chunk_terms': ('chunk_id', 'tokens'),
}
KNOWLEDGE_SCHEMA = r"""
            CREATE TABLE sources (source_id TEXT PRIMARY KEY, data_json TEXT NOT NULL);
            CREATE TABLE documents (document_id TEXT PRIMARY KEY, source_id TEXT, version TEXT, content_hash TEXT);
            CREATE TABLE chunks (chunk_id TEXT PRIMARY KEY, source_id TEXT, section_id TEXT, content_hash TEXT, data_json TEXT NOT NULL);
            CREATE VIRTUAL TABLE chunk_terms USING fts5(chunk_id UNINDEXED, tokens);
            """
KNOWLEDGE_DATABASE_MESSAGE = '活动知识库SQLite缺失或不可读取，请恢复配套资料版本；未自动创建或修复。'

class KnowledgeStore:
    def __init__(self, path: Path, create=False):
        options = {'code': 'KNOWLEDGE_DATABASE_UNAVAILABLE', 'message': KNOWLEDGE_DATABASE_MESSAGE}
        if create:
            initialize_database(path, KNOWLEDGE_SCHEMA, KNOWLEDGE_TABLES, **options)
        else:
            validate_database(path, KNOWLEDGE_TABLES, **options)
        self.db = open_existing(path, **options)
        self.db.row_factory = sqlite3.Row

    def add(self, source: dict, chunks: list[dict]):
        sid = source['source_id']
        self.db.execute('INSERT INTO sources VALUES (?,?)', (sid, json.dumps(source, ensure_ascii=False)))
        self.db.execute('INSERT INTO documents VALUES (?,?,?,?)', ('doc-' + sid, sid, source['document_version'], source['content_hash']))
        for chunk in chunks:
            self.db.execute('INSERT INTO chunks VALUES (?,?,?,?,?)', (chunk['chunk_id'], sid, chunk['section_id'], chunk['content_hash'], json.dumps(chunk, ensure_ascii=False)))
            text = chunk['content'] + ' ' + ' '.join(chunk['entity_names'])
            self.db.execute('INSERT INTO chunk_terms VALUES (?,?)', (chunk['chunk_id'], lexical_tokens(text)))
        self.db.commit()

    def chunk(self, chunk_id: str) -> dict:
        row = self.db.execute('SELECT c.data_json,s.data_json AS source_json FROM chunks c JOIN sources s USING(source_id) WHERE chunk_id=?', (chunk_id,)).fetchone()
        if not row: raise ValueError('Evidence ID does not exist in canonical database')
        chunk, source = json.loads(row['data_json']), json.loads(row['source_json'])
        return {**chunk, 'source': source}

    def lexical_search(self, question: str, limit=10, entity_terms=None) -> list[dict]:
        terms = lexical_tokens(question).split() if entity_terms is None else list(dict.fromkeys(token for entity in entity_terms for token in ([entity] if len(entity) <= 2 else [entity[i:i+2] for i in range(len(entity)-1)])))
        if not terms: return []
        # Tokens are generated alphanumerics/Chinese, quoted and bound; no user MATCH syntax.
        expression = ' OR '.join('"' + term + '"' for term in terms[:100])
        rows = self.db.execute('SELECT chunk_id,bm25(chunk_terms) AS score FROM chunk_terms WHERE chunk_terms MATCH ? ORDER BY score LIMIT ?', (expression, limit)).fetchall()
        return [{'chunk_id': r['chunk_id'], 'keyword_score': float(r['score'])} for r in rows]

    def sources(self) -> list[dict]:
        return [json.loads(r[0]) for r in self.db.execute('SELECT data_json FROM sources ORDER BY source_id')]

    def all_chunks(self) -> list[dict]:
        return [json.loads(r[0]) for r in self.db.execute('SELECT data_json FROM chunks ORDER BY chunk_id')]

    def count(self):
        return self.db.execute('SELECT count(*) FROM chunks').fetchone()[0]

    def close(self): self.db.close()

